import {asset} from './core.mjs';

// Each effect owns its presets and predicates; this shell only presents them.
export function filmstrip(stage, scenes) {
  const footer=document.querySelector('.study-footer'),strip=footer.querySelector('.study-strip');
  const id=document.body.dataset.study,items=scenes.items;
  document.querySelector('#study-atlas-label').textContent=scenes.label;
  document.querySelector('#study-total').textContent='/ '+String(items.length).padStart(2,'0');
  strip.style.setProperty('--scene-count',items.length);
  let current=-2;
  const reveal=button=>{const a=button.getBoundingClientRect(),b=strip.getBoundingClientRect();strip.scrollLeft+=a.left-b.left-(strip.clientWidth-a.width)/2;};
  const buttons=items.map((item,index)=>{
    const button=document.createElement('button');button.type='button';button.className='hall-card study-card';button.dataset.scene=item.id;
    const thumb=document.createElement('span');thumb.className='hall-thumb';
    const img=document.createElement('img');img.src=asset(item.image || `studies/filmstrip/${id}-${item.id}.webp`);img.alt='';img.width=160;img.height=96;thumb.append(img);
    const copy=document.createElement('span');copy.className='hall-card-copy';
    const number=document.createElement('small');number.textContent=String(index+1).padStart(2,'0')+' / '+scenes.kind;
    const title=document.createElement('strong');title.textContent=item.title;copy.append(number,title);button.append(thumb,copy);
    button.addEventListener('click',()=>{item.apply();stage.dirty=true;sync();reveal(button);});
    // On portal's mobile strip, pointer focus must not move the target before click.
    button.addEventListener('focus',()=>{if(id!=='portal'||button.matches(':focus-visible'))reveal(button);});strip.append(button);return button;
  });
  function sync(){
    const index=items.findIndex(item=>item.active());
    if(index===current)return;
    current=index;
    buttons.forEach((button,i)=>{button.setAttribute('aria-pressed',String(i===index));if(i===index)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current');});
    document.querySelector('#study-current').textContent=index<0?'—':String(index+1).padStart(2,'0');
    footer.style.setProperty('--hall-position',Math.max(0,index)/(items.length-1));
    footer.classList.toggle('study-custom',index<0);
    if(index>=0)reveal(buttons[index]);
  }
  document.querySelector('#study-prev').addEventListener('click',()=>buttons[(Math.max(0,current)-1+items.length)%items.length].click());
  document.querySelector('#study-next').addEventListener('click',()=>buttons[(current+1)%items.length].click());
  stage.onRendered=sync;sync();
}

"""Offline-only browser harness. Does not change the production sources.
Uses isolated IIFEs and in-memory asset data URLs when the test environment
forbids navigation. Static graph checks separately verify native ES-module paths.
"""
from pathlib import Path
import re,json,base64
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
ORDER=['math','core','filmstrip','portal','fluid','temporal','optical','shadow','folding']

def bundle(video_fixture: Path | None = None):
    entries=[]
    image_types={'.svg':'image/svg+xml','.png':'image/png','.webp':'image/webp'}
    assets={p.relative_to(ROOT/'assets').as_posix():'data:'+image_types[p.suffix]+';base64,'+base64.b64encode(p.read_bytes()).decode() for p in (ROOT/'assets/studies').rglob('*') if p.suffix in image_types}
    if video_fixture:
        assets['matrix-battle/03-clash.mp4']='data:video/mp4;base64,'+base64.b64encode(video_fixture.read_bytes()).decode()
    for name in ORDER:
        src=(ROOT/'src/studies'/f'{name}.mjs').read_text(encoding='utf-8')
        exports=re.findall(r'export\s+(?:async\s+)?(?:function|class|const)\s+(\w+)',src)
        src=re.sub(r"import\s*\{([^}]+)\}\s*from\s*'./([^']+)';",lambda m:f'const {{{m[1]}}}=M[{json.dumps(m[2])}];',src)
        if name=='core':
            src=re.sub(r"export const ASSETS = .*?;",'export const ASSETS = null;',src)
            src=re.sub(r"export const asset = .*?;",'export const asset = name => ASSET_DATA[name] || "data:video/mp4;base64,";',src)
        src=re.sub(r'\bexport\s+','',src)
        entries.append(f'M["{name}.mjs"]=(()=>{{\n{src}\nreturn {{{",".join(exports)}}};\n}})();')
    main=(ROOT/'src/studies/main.mjs').read_text(encoding='utf-8')
    main=re.sub(r"import\s*\{([^}]+)\}\s*from\s*'./([^']+)';",lambda m:f'const {{{m[1]}}}=M[{json.dumps(m[2])}];',main)
    main=re.sub(r"import\('./([^']+)'\)",lambda m:f'Promise.resolve(M[{json.dumps(m[1])}])',main)
    shell=(ROOT/'src/hall/main.js').read_text(encoding='utf-8')
    return shell+'\nconst ASSET_DATA='+json.dumps(assets)+';const M={};\n'+'\n'.join(entries)+'\n(async()=>{\n'+main+'\n})();'

def inline_page(slug):
    s=(ROOT/'dist'/f'{slug}.html').read_text(encoding='utf-8')
    s=re.sub(r'<link rel="stylesheet" href="([^"]+)"[^>]*>',lambda m:'<style>'+(ROOT/'dist'/m[1]).resolve().read_text(encoding='utf-8')+'</style>',s)
    s=re.sub(r'<script\b(?![^>]*type="application/json")[^>]*>.*?</script>','',s,flags=re.S)
    def thumbnail(match):
        path=(ROOT/'dist'/match[1]).resolve()
        return 'src="data:image/webp;base64,'+base64.b64encode(path.read_bytes()).decode()+'"'
    s=re.sub(r'src="(../assets/studies/atlas/[^\"]+)"',thumbnail,s)
    return s
