.hall-modes a:focus-visible,.hall-atlas a:focus-visible,.hall-open-atlas:focus-visible,.hall-close-atlas:focus-visible{outline:2px solid var(--accent,#bdb4ff);outline-offset:3px}.hall-modes a:focus-visible{outline-offset:-2px}.hall-open-atlas,.hall-close-atlas{border:0;background:none;padding:0;cursor:pointer;text-align:left;color:#d4c4a0;font-size:9px;line-height:1.5}.hall-open-atlas:hover,.hall-close-atlas:hover{color:#fff}
